        .to_public_key_pem(rsa::pkcs8::LineEnding::default())
        .map_err(|err| JwtError::Jwks(format!("pem: {err}")))?;
    DecodingKey::from_rsa_pem(pem.as_bytes())
        .map_err(|err| JwtError::Jwks(format!("decoding key: {err}")))
}

